import heapq
import itertools


def _temporal(policy):
    def solve(data):
        required = data.get("required", [])
        required_bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = required_bits.get(source, 0)
        initial = (source, initial_mask, 0)
        start = data["start"]
        distances = {initial: start}
        queue = [(start, source, initial_mask, 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and (
                    policy["coupon_rule"] == "at_most" or used == data["coupons"]):
                return {"arrival": time}
            for edge in (e for e in data["edges"] if e["u"] == node):
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < data["coupons"]:
                    discounted = max(policy["minimum_duration"],
                                     edge["duration"] - edge.get("discount", 0))
                    options.append((discounted, used + 1))
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    dest = edge["v"]
                    next_mask = mask | required_bits.get(dest, 0)
                    next_state = (dest, next_mask, next_used)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, dest, next_mask, next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    def rounded(n, d):
        if data["rounding"] == "half_up":
            return (n + d // 2) // d
        return n // d

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    domains = [[-1] + sorted(row["version"] for row in packages[name])
               for name in names]
    best_vector = None
    best = None

    for vector in itertools.product(*domains):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        valid = True
        for name, bounds in roots.items():
            version = selected.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        for name, version in selected.items():
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                valid = False
                break

        if not valid:
            continue
        edges = {}
        for name, version in selected.items():
            row = next(row for row in packages[name] if row["version"] == version)
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = selected.get(dep["name"])
                if target is None or not dep["min"] <= target <= dep["max"]:
                    valid = False
                    break
                active.append(dep["name"])
            edges[name] = active
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in reachable):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = selected

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _jobs(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    options = [job for job in jobs if job["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    k = data["k"]
    best_value = None
    best_ids = None

    for subset in itertools.combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in data.get("quotas", {}).items()):
            continue

        active_ends = []
        compatible = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                compatible = False
                break
        if not compatible:
            continue

        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": _temporal({"coupon_rule": "exact", "minimum_duration": 2}),
    "component_02": _temporal({"coupon_rule": "at_most", "minimum_duration": 1}),
    "component_03": _temporal({"coupon_rule": "exact", "minimum_duration": 1}),
    "component_04": _temporal({"coupon_rule": "at_most", "minimum_duration": 2}),
    "component_05": _temporal({"coupon_rule": "exact", "minimum_duration": 2}),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _jobs,
}
